-- ============================================================
-- 077 · EZ2DJ 7th TRAX BONUS EDITION revision A 서열표 (채보만 · 투표 없음)
--
-- ─── 무엇을 만드는가 ─────────────────────────────────────
-- EZ2DJ 의 여섯 번째 버전, 흔히 **BErA** 로 부르는 것입니다. 곡 258개 · 채보
-- **2,445개** — 지금까지 넣은 버전 중 가장 큽니다.
-- 059 · 060 · 074 · 075 · 076 과 같이 **투표는 넣지 않아** 전부 '미정' 입니다.
--
-- ─── 출처 ────────────────────────────────────────────────
--   나무위키 『EZ2DJ 7th TRAX BONUS EDITION revision A/수록곡』 목록
--   https://namu.wiki/w/EZ2DJ 7th TRAX BONUS EDITION revision A/수록곡
--
-- 완전한 표이므로 075 · 076 처럼 **표 하나를 그대로** 싣습니다. 앞 버전의 채보를
-- 참조하지 않습니다.
--
-- ⚠ 문서 머리가 "후기판, **버전별 올송을 기준**으로 한다" 고 적습니다. 기본 상태로는
--   고를 수 없는 채보가 표에 섞여 있다는 뜻입니다. 어느 곡이 그런지는 문서 맨 아래가
--   모드별로 적어 두는데, 서열표에는 '해금했는가' 를 담을 칸이 없어 **옮기지
--   않습니다.** 이 표는 "다 열었을 때 있는 채보" 로 읽어야 합니다.
--
-- ─── 표가 가로로 20칸입니다 ──────────────────────────────
--   Ruby N·H │ 5Street E·N·H·S │ 7Street E·N·H·S │ Club E·N·H │ Space N·H
--   │ Catch E·N·H │ Turn N·H
--
-- 076(CV)의 16칸에서 넷이 늘었습니다 — **Club EZ · Catch EZ · Catch HD · Turn HD**.
-- 난이도 이름은 그대로라 machine_difficulties 는 손대지 않습니다. 늘어난 것은
-- 그 난이도를 쓰는 모드입니다.
--
-- ─── 곡이 다시 크게 늡니다 (162 → 258) ───────────────────
-- CV 는 라이선스 만료로 곡이 줄었던 버전인데(192 → 162), BErA 는 반대로 96곡이
-- 늡니다. 셋이 섞여 있습니다.
--
--   ① BErA 신곡 — A Final Dreaming · Apollon · Atomizer · BLEED · Messier 333 ·
--      Pair Creation · Rosen Vampir · Return to Universe · 없잖아 · 적월애 ·
--      주문을 외워봐 · 하나뿐인 당신에게 … (한국어 제목 넷 포함)
--   ② 1st · SE 시절 곡의 재부활 — Bob · For 3 Weeks · Love & Extasy ·
--      Love & Extasy (Remix) · My Honey · Let It Go(원곡) ·
--      Get the beat (Nimble Mix) · Theme of EZ2DJ~Special Edition Ver.~
--   ③ 앞 버전에서 줄이 없어 못 넣었던 것 — R-decision (2.0 · CV 에서 라디오 전용)
--
-- 새로 들어오는 곡은 **51개**입니다 (아래 ⑤ 의 접미사 줄 다섯을 포함).
--
-- ─── ⚠ 한 칸에 숫자가 둘인 곳 (DIEOXIN) ──────────────────
-- 표에 딱 두 칸, 숫자가 둘씩 들어 있습니다.
--
--   DIEOXIN  Club HD  `12 15`   각주: "EX. AE에서 13으로 강등… EV에서 SHD로 부활"
--   DIEOXIN  Space HD `10 14`   각주: "AN Disc. EV 현재의 SHD"
--
-- 각주가 말하는 **EX · AN Disc** 는 E·N·H·S 축 밖의 채보입니다. SHD 로 적으면
-- 한참 뒤 버전(EV)의 이름을 이 버전에 붙이는 것이 되고, 버리면 채보가 사라집니다.
-- 그래서 059 가 히든 패턴에 한 대로 **같은 칸의 채보 하나 더**로 넣습니다 —
-- 레벨이 달라 채보 열쇠에 걸리지 않습니다. 아래 5) 의 `string_to_array` 가 이
-- 두 칸을 공백으로 쪼갭니다.
--
-- ─── ⚠ 레벨이 없는 칸 11개 (`☠` 5 · `?` 6) ───────────────
-- 둘 다 `charts.level` 을 NULL 로 넣어 `Lv.?` 칸에 모읍니다.
--
--   `?` 6개 — 神威 · Irregular Liner · Return to Universe · Rosen Vampir 의 Club HD,
--             Rosen Vampir · The Luna 의 Space NM. 문서가 값을 안 적은 칸입니다.
--   `☠` 5개 — 값이 아니라 **매길 수 없다는 표시**입니다.
--             Theme of EZ2DJ~Special Edition Ver.~ 의 5Street NM 하나와,
--             Catch 의 넷 — 1.5 때 나왔다가 다음 버전에서 삭제된 이른바
--             **EZ2CATCH 4대 천왕**이 BErA 에서 부활한 것입니다.
--
-- ─── ⚠ 접미사 줄 다섯을 곡으로 둡니다 (076 과 다릅니다) ──
-- 076(CV)은 `곡명 -HARD-` 줄을 **같은 곡의 HD 채보**로 넣었습니다. BErA 에서는
-- 그 방법이 통하지 않습니다 — HD 자리가 이미 차 있습니다.
--
--   Hyper Magic            Catch N 13 · **H 16** 이 둘 다 있는데 -ANOTHER- 가 또 있음
--   The Prince of Darkness Catch N 15 · **H 16** 이 둘 다 있는데 -ANOTHER- 가 또 있음
--   La Grand Bleu          Catch N 11 · **H 14** 가 둘 다 있는데 -HARD- 가 또 있음
--   Gray Hunter            Catch N 10 뿐 (HD 가 비어 있음)
--   Legend of Moonlight    Catch N 12 뿐 (HD 가 비어 있음)
--
-- 다섯 중 셋이 충돌하므로 균일한 규칙이 서지 않습니다. "비면 HD, 차면 곡" 처럼
-- 갈라 붙이는 것이 더 나쁩니다. 그래서 **문서가 준 이름 그대로 곡**으로 둡니다 —
-- 네 개의 4대 천왕은 그 이름으로 불리는 채보이기도 합니다.
--
-- ⚠ `weep Irish -RE-` 는 접미사 표시가 아니라 **곡 이름 자체**입니다 (2.0 신곡).
--
-- ─── 곡 이름 ─────────────────────────────────────────────
-- 별칭 54줄. 47줄은 대소문자 · 구두점만 다른 것이고, 7줄이 `값으로 확인` —
-- 겹치는 칸의 난이도가 **모두 같아서** 같은 곡으로 판정한 것입니다.
--
--   Confete (Evening Mix)    = Confete ~ Remix ~        (CV 와 5칸 일치)
--   Judgement                = Judgment                 (8칸 일치)
--   Metagalactic G-1000      = Metagalactic             (11칸 일치 · BErA 가 부제를 붙임)
--   One Two Three Four       = 1234                     (12칸 일치)
--   Theme of EZ2DJ 2         = Ez2Dj (찬가 II)          (10칸 일치)
--   With U Girl (Beach Ver.) = With you Girl Beach Ver. (6칸 일치)
--   Look Out (EK2-Beat Ver.) = Look Out EK1-Beat Ver.   (5칸 일치)
--
-- ⚠ 마지막 줄은 **문서 쪽 오타로 보입니다.** 이 계열은 6th 때부터
--   `Look Out` 이 EK1, `The Boy` 가 EK2 인데 BErA 문서는 둘 다 EK2 로 적었습니다.
--   값이 EK1 쪽과 5칸 모두 같고 `The Boy (EK2-Beat Ver.)` 줄이 따로 있어,
--   **이미 있는 EK1 곡에 붙입니다.**
--
-- ⚠ 문서가 **단어 중간에 줄바꿈**을 넣은 곡이 둘 있습니다
--   (`Aquaris (Physical Inspir` + `ation Hyper Blue Mix)`). 아래 3) 에는 이어 붙여
--   적었습니다 — 원문 대조 시 그 줄만 모양이 다릅니다.
--
-- ─── 난이도 상한은 18 그대로 ─────────────────────────────
-- 076 에서 18 로 올랐고 BErA 도 18 입니다 (Hyper Magic 의 Space HD,
-- Return to Universe · Rosen Vampir 의 Catch HD, 神威 의 Catch HD).
--
-- ─── 여러 번 실행해도 결과가 같습니다 ────────────────────
-- 행은 전부 ON CONFLICT DO NOTHING. 쪼갠 뒤에도 (곡, 모드, 난이도, 레벨)이
-- 완전히 같은 줄은 없는 것을 확인했습니다.
-- `level_label` 이 있는 DB 에서도 도는 이유는 059 · 060 머리말과 같습니다.
--
-- 되돌리려면: MIGRATION_FILES 에서 빼고 schema_migrations 에서 지운 뒤
--   DELETE FROM charts WHERE version_id =
--     (SELECT id FROM game_versions WHERE machine_id = 10 AND code = '7thBErA');
--   DELETE FROM game_versions WHERE machine_id = 10 AND code = '7thBErA';
--   DELETE FROM songs WHERE machine_id = 10 AND id NOT IN (SELECT song_id FROM charts);
-- ============================================================

-- ─── 1) 7th TRAX BErA ─────────────────────────────────────
ON CONFLICT DO NOTHING;

-- ─── 2) 곡 이름 별칭 (BErA 표기 → 이미 있는 이름) ─────────
CREATE TEMP TABLE ez2dj_bera_alias (wiki TEXT, canon TEXT);


-- ─── 3) 출처 표 그대로 ────────────────────────────────────
-- 컬럼 차례가 문서의 가로 차례와 같습니다. 한 줄이 문서의 한 줄입니다.
-- `-` 는 채보 없음, `?` 는 레벨 미상, `☠` 는 레벨을 매길 수 없다는 표시입니다.
CREATE TEMP TABLE ez2dj_bera (
  title TEXT,
  ruby_n TEXT, ruby_h TEXT,
  s5e TEXT, s5n TEXT, s5h TEXT, s5s TEXT,
  s7e TEXT, s7n TEXT, s7h TEXT, s7s TEXT,
  club_e TEXT, club_n TEXT, club_h TEXT,
  sp_n TEXT, sp_h TEXT,
  cat_e TEXT, cat_n TEXT, cat_h TEXT,
  turn_n TEXT, turn_h TEXT
);


-- ─── 4) 곡 (새로 들어오는 51곡만 늘어납니다) ──────────────
SELECT DISTINCT 10, COALESCE(a.canon, t.title), NULL
FROM ez2dj_bera t
LEFT JOIN ez2dj_bera_alias a ON a.wiki = t.title
ON CONFLICT DO NOTHING;

-- ─── 5) 채보 2,445개 ──────────────────────────────────────
-- 가로 20칸을 세로로 펼칩니다. 한 칸에 숫자가 둘인 DIEOXIN 두 칸은 공백으로 쪼개
-- 채보 둘이 됩니다 (머리말 참고). `?` 와 `☠` 는 레벨을 NULL 로 남깁니다.
CREATE TEMP TABLE ez2dj_bera_charts AS
SELECT COALESCE(a.canon, t.title) AS title,
       v.mode,
       v.difficulty,
       CASE WHEN x.one IN ('?', '☠') THEN NULL ELSE x.one::int END AS level
FROM ez2dj_bera t
LEFT JOIN ez2dj_bera_alias a ON a.wiki = t.title
CROSS JOIN LATERAL (VALUES
  ('RUBY',  'NM',  t.ruby_n),
  ('RUBY',  'HD',  t.ruby_h),
  ('5ST',   'EZ',  t.s5e),
  ('5ST',   'NM',  t.s5n),
  ('5ST',   'HD',  t.s5h),
  ('5ST',   'SHD', t.s5s),
  ('7ST',   'EZ',  t.s7e),
  ('7ST',   'NM',  t.s7n),
  ('7ST',   'HD',  t.s7h),
  ('7ST',   'SHD', t.s7s),
  ('CLUB',  'EZ',  t.club_e),
  ('CLUB',  'NM',  t.club_n),
  ('CLUB',  'HD',  t.club_h),
  ('SPACE', 'NM',  t.sp_n),
  ('SPACE', 'HD',  t.sp_h),
  ('CATCH', 'EZ',  t.cat_e),
  ('CATCH', 'NM',  t.cat_n),
  ('CATCH', 'HD',  t.cat_h),
  ('TURN',  'NM',  t.turn_n),
  ('TURN',  'HD',  t.turn_h)
) AS v(mode, difficulty, val)
CROSS JOIN LATERAL unnest(string_to_array(v.val, ' ')) AS x(one)
WHERE v.val NOT IN ('X', '-', '');

-- 컬럼 목록을 DB 상태에 맞춰 짭니다 — 059 머리말의 `level_label` 항목 참고.
DO $mig$
DECLARE
  has_label BOOLEAN := EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'charts' AND column_name = 'level_label'
  );
BEGIN
  EXECUTE format($q$
    SELECT s.id, gv.id, e.mode, e.difficulty, e.level%s
    FROM ez2dj_bera_charts e
    JOIN songs s          ON s.machine_id  = 10 AND s.title = e.title
    JOIN game_versions gv ON gv.machine_id = 10 AND gv.code = '7thBErA'
    ON CONFLICT DO NOTHING
  $q$,
    CASE WHEN has_label THEN ', level_label'                    ELSE '' END,
    CASE WHEN has_label THEN ', COALESCE(e.level::text, ''?'')' ELSE '' END);
END
$mig$;

DROP TABLE ez2dj_bera_charts;
DROP TABLE ez2dj_bera;
DROP TABLE ez2dj_bera_alias;

-- ─── 6) 집계 캐시 초기화 ──────────────────────────────────
SELECT recalc_chart_stats(c.id)
FROM charts c JOIN songs s ON s.id = c.song_id
WHERE s.machine_id = 10;
